    private void notifyWatchers(String user, Person person, Claim claim) {
        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
            audit.change("NOTIFY", claim.getSheetId(), user, "user=" + watch.getUser(), "person=" + person.getName(),
                    "number=" + claim.getNumber());
        }
    }

    /** The number a claim due by {@code date} is given when settled now: within the period containing
     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
     * period, otherwise the next sheet-wide number in the fiscal year of that date ({@code FY<yyyy>-<n>}). */
    public String nextNumber(String sheetId, LocalDate date) {
        if (!sheets.numbersByPeriod(sheetId)) return sheets.nextClaimNumber(sheetId, date);
        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
                .findFirst()
                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
    }

    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
     * the user is a clerk and the due is above the clerk limit in force on the sheet's today (the person's
     * grade's own then, else the sheet's). */
    private boolean overLimit(String sheetId, String user, Person person, BigDecimal due) {
        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
        BigDecimal limit = settings.clerkLimitFor(sheetId, person.gradeOn(sheets.today(sheetId)));
        return limit != null && due.compareTo(limit) > 0;
    }

    /** Refuse a settle or approval of the claim, whose due is {@code due}, when that due is above the proof
     * threshold in force on its date (its person's grade's own then, else the sheet's; a due that is n/a is
     * within any threshold) while it has no proofs, or, while the sheet lists proof kinds, no proof of one
     * of them. */
    private void refuseUnproved(Claim claim, Person person, BigDecimal due) {
        if (due == null) return;
        String kinds = settings.proofKinds(claim.getSheetId());
        boolean proved = claim.getProofs() > 0 && (kinds == null
                || Arrays.stream(kinds.split(",")).allMatch(kind -> claim.getProofsOf(kind) > 0));
        if (proved) return;
        BigDecimal threshold = settings.proofThresholdFor(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
    }

    /** Whether an open of the claim goes to REVIEW: its due as it shows now is above the review threshold
     * in force on its date (a due that is n/a is within any threshold). */
    private boolean overReview(Claim claim, Person person) {
        BigDecimal due = rollup.shownOf(claim, person);
        if (due == null) return false;
        BigDecimal threshold = settings.reviewThresholdOn(claim.getSheetId(), claim.getDate());
        return threshold != null && due.compareTo(threshold) > 0;
    }
