@GetMapping("/claims/duplicates")
public List<String> duplicates(@PathVariable @NotBlank @Size(max = 100) String sheetId,
        @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
    return service.duplicates(sheetId.trim());
}

