protected dueTotalOf(person: Person): string | null {
  const due = this.dueCentsOf(person);
  return due === null ? null : money(due);
}

/** How far the sum of the person's figures is above what the cap leaves them (see {@link capLeftOf});
 *  0.00 when it is not, when there is no cap, or when their due-total is n/a. */
protected excessOf(person: Person): string {
  const sum = this.sumCentsOf(person);
  const left = this.capLeftOf(person);
  return money(sum === null || left === null ? 0 : Math.max(0, sum - left));
}

/** The person's due-total in cents, capped; null when it is n/a. */
private dueCentsOf(person: Person): number | null {
  const sum = this.sumCentsOf(person);
  const left = this.capLeftOf(person);
  return sum === null || left === null ? sum : Math.min(sum, left);
}

/** The most the person's due-total can be, in cents: the sheet's cap less their cut total, not below 0;
 *  null when there is no cap. */
private capLeftOf(person: Person): number | null {
  const cap = this.cap();
  return cap === null ? null : Math.max(0, cap - (this.cutCents().get(person.id) ?? 0));
}

/** The sum of the person's figures in cents, before the cap; null when it is n/a. */
private sumCentsOf(person: Person): number | null {
  const split = this.splitOf(person);
  return split.any || this.rateOf(this.gradeNow(person)) !== null ? split.settled + split.open : null;
}

/** How many of the person's own claims are in the status. */
protected statusCountOf(person: Person, status: Claim['status']): number {
  return this.claimsOf(person.id).filter((c) => c.status === status).length;
}

/** What is due on the person's own counting SETTLED claims (at their frozen figures) and on their
 *  counting OPEN and PENDING ones, in cents, each claim whole as it shows it: shares of a claim are
 *  not taken from it, nor are the parts the person holds of others' claims added. */
protected claimedSplitOf(person: Person): { settled: number; open: number } {
  let settled = 0;
  let open = 0;
  for (const c of this.claimsOf(person.id)) {
    if (!this.countsLive(c, person)) continue;
    const due = claimShownCents(c, this.rates(), person.grades, this.floors(), this.lateness(), this.roundingOf(person.id));
    if (due === null) continue;
    if (isOpen(c)) open += due;
    else settled += due;
  }
  return { settled, open };
}

/** The person's figures before the cap, in cents, split in two: what is due on their counting SETTLED
 *  claims (at their frozen figures) and on their counting OPEN and PENDING ones, as each claim shows
 *  it (a claim with nothing due is skipped); with whether any claim had a figure. */
protected splitOf(person: Person): { settled: number; open: number; any: boolean } {
  let settled = 0;
  let open = 0;
  let any = false;
  for (const c of this.claimsOf(person.id)) {
    if (!this.countsLive(c, person)) continue;
    const due = claimShownCents(c, this.rates(), person.grades, this.floors(), this.lateness(), this.roundingOf(person.id));
    if (due === null) continue;
    const own = c.shares.reduce((left, s) => left - (this.sharePartOf(c, s, due, person.id) ?? 0), due);
    if (isOpen(c)) open += own;
    else settled += own;
    any = true;
  }
  const held = this.heldParts().get(person.id);
  if (held) {
    settled += held.settled;
    open += held.open;
    any = true;
  }
  return { settled, open, any };
}

/** The parts each person holds of others' claims, in cents, by person id: of every claim that counts
 *  for its own person and has a figure, their part by their share (see sharePartCents; none when their
 *  grade has no rate then); split by whether the claim is SETTLED or OPEN and PENDING. */
private readonly heldParts = computed(() => {
  const byId = new Map(this.people().map((p) => [p.id, p]));
  const by = new Map<number, { settled: number; open: number }>();
  for (const c of this.claims()) {
    const owner = byId.get(c.personId);
    if (c.shares.length === 0 || owner === undefined || !this.countsLive(c, owner)) continue;
    const due = claimShownCents(c, this.rates(), owner.grades, this.floors(), this.lateness(), this.roundingOf(owner.id));
    if (due === null) continue;
    for (const s of c.shares) {
      const part = this.sharePartOf(c, s, due, owner.id);
      if (part === null) continue;
      const held = by.get(s.personId) ?? { settled: 0, open: 0 };
      if (isOpen(c)) held.open += part;
      else held.settled += part;
      by.set(s.personId, held);
    }
  }
  return by;
});

/** The part of the claim of `ownerId`, whose due as it shows is `due` cents, its holder holds by the
 *  share `s` (see sharePartCents); null when the holder's grade has no rate on the claim's date. */
private sharePartOf(c: Claim, s: { personId: number; share: string }, due: number, ownerId: number): number | null {
  const holder = this.people().find((p) => p.id === s.personId);
  return sharePartCents(c, s.share, due, this.rates(), holder?.grades ?? null, this.roundingOf(ownerId));
}

/** What is due on the person's counting SETTLED claims that are not corrections, in cents, as each
 *  claim shows it, before the cap: the settled figure their score is worked from. */
private scoredSettledOf(person: Person): number {
  let settled = 0;
  for (const c of this.claimsOf(person.id)) {
    if (!this.countsLive(c, person) || isOpen(c) || isCorrection(c)) continue;
    settled += claimShownCents(c, this.rates(), person.grades, this.floors(), this.lateness(), this.roundingOf(person.id)) ?? 0;
  }
  return settled;
}

/** How many of the person's counting claims are overdue, and the sum of what is due on them, in
 *  cents, as each claim shows it (a claim with nothing due adds nothing). */
protected overdueOf(person: Person): { count: number; cents: number } {
  let count = 0;
  let sum = 0;
  const today = this.session.today();
  for (const c of this.claimsOf(person.id)) {
    if (!this.countsLive(c, person) || !overdue(c, today, overdueFrom(c, person.grades, this.graces()))) continue;
    count++;
    sum += claimShownCents(c, this.rates(), person.grades, this.floors(), this.lateness(), this.roundingOf(person.id)) ?? 0;
  }
  return { count, cents: sum };
}

/** The person's score: their settled-total, leaving out corrections, divided by 100, minus 5 for
 *  every overdue claim that counts, rounded half to even to a whole number. */
protected scoreOf(person: Person): string {
  // In cents, the score is (settled - 50000 * overdue) / 10000.
  const x = this.scoredSettledOf(person) - 50000 * this.overdueOf(person).count;
  const q = Math.floor(x / 10000);
  const r = x - q * 10000;
  const whole = r > 5000 || (r === 5000 && q % 2 !== 0) ? q + 1 : q;
  return String(whole === 0 ? 0 : whole);
}

/** The person's band while both score thresholds are set: HIGH at or above the high one, MID at or
 *  above the mid one, else LOW; blank while either is not set. */
protected bandOf(person: Person): string {
  const { mid, high } = this.scoreThresholds();
  if (mid === null || high === null) return '';
  const score = Number(this.scoreOf(person));
  return score >= high ? 'HIGH' : score >= mid ? 'MID' : 'LOW';
}

/** What is due on the person's counting OPEN and PENDING claims, in cents, as each claim shows it,
 *  split by the claim's age on the sheet's today (the days from its date): 0 to 30 days (a claim
 *  dated after today included), 31 to 60, and 61 or more. */
protected agedOf(person: Person): [number, number, number] {
  const aged: [number, number, number] = [0, 0, 0];
  const today = this.session.today();
  if (today === null) return aged;
  for (const c of this.claimsOf(person.id)) {
    if (!isOpen(c) || !this.countsLive(c, person)) continue;
    const due = claimShownCents(c, this.rates(), person.grades, this.floors(), this.lateness(), this.roundingOf(person.id));
    if (due === null) continue;
    const age = daysBetween(c.date, today);
    aged[age <= 30 ? 0 : age <= 60 ? 1 : 2] += due;
  }
  return aged;
}

protected periodAdded(period: Period): void {
  this.periods.update((list) => [...list, period]);
}

/** Put a closed, reopened, locked or unlocked period in its place. */
protected periodClosed(period: Period): void {
  this.periods.update((list) => list.map((p) => (p.id === period.id ? period : p)));
}

/** Re-read the sheet's claims: an added holiday re-fixes their due-by on the server. */
protected async holidayAdded(): Promise<void> {
  const sheet = this.sheet();
  if (!sheet) return;
  try {
    const claims = await this.claimsService.list(sheet);

